using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Inventory.Domain;
public sealed class StockMovement:Entity<Guid>{private StockMovement(){}private StockMovement(Guid id,Guid tenantId,Guid itemId,short typeId,Guid? sourceId,Guid? destinationId,Guid actorId,decimal quantity,string reference){if(tenantId==Guid.Empty||itemId==Guid.Empty||actorId==Guid.Empty)throw new ArgumentException("Movement references are required.");if(typeId<=0||quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));if(sourceId is null&&destinationId is null)throw new ArgumentException("A movement endpoint is required.");if(sourceId==destinationId)throw new ArgumentException("Source and destination must differ.");Id=id;TenantId=tenantId;ItemId=itemId;MovementTypeId=typeId;SourceWarehouseId=sourceId;DestinationWarehouseId=destinationId;ActorUserId=actorId;Quantity=decimal.Round(quantity,3);Reference=InventoryRules.Text(reference,120);OccurredAtUtc=DateTimeOffset.UtcNow;}public Guid TenantId{get;private set;}public Guid ItemId{get;private set;}public short MovementTypeId{get;private set;}public Guid? SourceWarehouseId{get;private set;}public Guid? DestinationWarehouseId{get;private set;}public Guid ActorUserId{get;private set;}public decimal Quantity{get;private set;}public string Reference{get;private set;}=string.Empty;public DateTimeOffset OccurredAtUtc{get;private set;}public static StockMovement Record(Guid tenantId,Guid itemId,short typeId,Guid? sourceId,Guid? destinationId,Guid actorId,decimal quantity,string reference)=>new(Guid.NewGuid(),tenantId,itemId,typeId,sourceId,destinationId,actorId,quantity,reference);}
